def safe_float(val):
    try:
        if isinstance(val, (list, np.ndarray, pd.Series)):
            val = val[0] if len(val) > 0 else None
        if val is None or pd.isna(val) or val == "": return 0.0
        return float(val)
    except: return 0.0

def _blank(v):
    try: return v is None or (isinstance(v, str) and v.strip() == "") or pd.isna(v)
    except Exception: return False
def _or(v, d):
    """Number from a feed cell; an empty cell gives the default d."""
    return d if _blank(v) else safe_float(v)
def _name(v):
    return "" if _blank(v) else str(v).strip()

months = [f"M{i}" for i in range(1, 13)]
future_years = ["Year 2", "Year 3", "Year 4", "Year 5"]
display_columns = months + ["Year 1", "Year 2", "Year 3", "Year 4", "Year 5"]
RM_INFL_ROWS = [f"Year {y} Price Inflation (%)" for y in (2, 3, 4, 5)]
DEF_GST = 18.0                                             # default GST % (sale and RM purchase)
DEF_CUST_ADV = 10.0                                        # default customer advance %

# RM table of P4 and of every added product : one row per RM (rows can be added / deleted)
AP_RM_COLS = ["RM Name", "Consumption Ratio (%)", "Normal Loss - Scrap (%)", "Invisible Loss (%)", "Default Price (Rs/Kg)",
              "Days Hold of Inventory", "Supplier Advance (%)", "Supplier Credit Days", "M1 Op Stock (Kg)", "Opening Creditors (Rs Lacs)", "GST %"]
def _ap_rm_rows(df):
    rows = []
    if df is None: return rows
    for _, r in df.iterrows():
        nm = _name(r.get(AP_RM_COLS[0]))
        if not nm: continue
        g = lambda i, d=0.0: _or(r.get(AP_RM_COLS[i]), d)
        rows.append({"name": nm, "con": g(1), "vloss": g(2), "iloss": g(3), "price": g(4), "hold": g(5), "adv": g(6),
                     "credit": g(7), "opstock": g(8), "opcred": g(9), "gst": g(10, DEF_GST)})
    return rows

