def _sync_rm_table(df, names, defaults):
    """One row per RM in 'names' (same order): rows of RMs already there are kept, new RMs get default figures, RMs no longer in the BOM are dropped."""
    have = {_name(r): r for r in df.to_dict("records")}
    rows = [have.get(n, {"Raw Material": n, **defaults}) for n in names]
    out = pd.DataFrame(rows, columns=df.columns)
    out["Raw Material"] = names
    return out.reset_index(drop=True)
def _sync_base_rm_tables():
    names = _bom_names(st.session_state.bom_v2)
    for key, d in (("sidebar_rm_logistics_df", RM_LOG_DEF), ("rm_val_v2", RM_VAL_DEF)):
        cur = st.session_state[key]
        if [_name(x) for x in cur["Raw Material"]] != names:
            st.session_state[key] = _sync_rm_table(cur, names, d)
_sync_base_rm_tables()

