def _cost_pu(cost, qty):      # Rs lacs / Qt -> Rs per Kg ; Year columns = annual cost / annual Qt (weighted), not a sum of months
    return [(c * 100000.0 / q if q > 0 else 0.0) for c, q in zip(cost, qty)]
