_fragment = getattr(st, "fragment", None) or getattr(st, "experimental_fragment", None) or (lambda f: f)
_dialog = getattr(st, "dialog", None) or getattr(st, "experimental_dialog", None)

# Level colours of the PL / CF figures, and the expanded-heading colour
LVL_COLOR = {"L1": T_GOLD, "L2": "#FFFFFF", "L3": "#9FE8FF", "L4": "#C8CDD3"}
T_OPEN = "#39FF14"                                            # neon green : heading that is expanded

def tree_nodes(master):
    """For every row of a PL / CF tree table : node key, parent chain and whether it has children."""
    node_info, cur_l1, cur_l2, cur_l3 = [], None, None, None
    for i in range(len(master)):
        b_id, depth = str(master.at[i, "BlockID"]), master.at[i, "Depth"]
        if depth == "L1":
            node, anc = f"L1|{b_id}", []
            cur_l1, cur_l2, cur_l3 = node, None, None
        elif depth == "L2":
            node, anc = f"L2|{b_id}|{i}", [cur_l1]
            cur_l2, cur_l3 = node, None
        elif depth == "L3":
            node, anc = f"L3|{b_id}|{i}", [cur_l1, cur_l2]
            cur_l3 = node
        else:
            node, anc = f"L4|{b_id}|{i}", [cur_l1, cur_l2, cur_l3]
        child = {"L1": "L2", "L2": "L3", "L3": "L4"}.get(depth)
        has = (child is not None and i + 1 < len(master) and master.at[i + 1, "Depth"] == child and str(master.at[i + 1, "BlockID"]) == b_id)
        node_info.append({"node": node, "ancestors": anc, "has_children": has})
    return node_info

def tree_visible(master, sfx):
    """Row positions shown on screen for this tree (its own expand / collapse state)."""
    info = tree_nodes(master)
    open_nodes = st.session_state.setdefault(f"pl_open_nodes{sfx}", set())
    return [i for i, n in enumerate(info) if all(a in open_nodes for a in n["ancestors"])], info, open_nodes

def _fmt_val(v, fmt):
    v = safe_float(v)
    if fmt == "pct": return f"{v:,.2f}%"
    if fmt == "qt": return f"{v:,.0f}"
    if fmt in ("rate", "num"): return f"{v:,.2f}"
    return f"{v:,.2f} L"

_TREE_LBL = ["Si No", "Level 1", "Level 2", "Level 3", "Level 4"]
_CLICK_COLS = tuple(_TREE_LBL)

@_fragment
def _tree_fragment(master_pl, sfx, px):
    """One PL / CF tree. Clicking a heading ([+] / [-] in front of its text) expands / collapses it; only this table is redrawn (fragment), so it is quick."""
    master_pl = master_pl.reset_index(drop=True)
    visible_idx, node_info, open_nodes = tree_visible(master_pl, sfx)
    st.session_state[f"pl_row_map{sfx}"] = [(node_info[i]["node"], node_info[i]["has_children"]) for i in visible_idx]

    def _click_cb():
        ver = st.session_state.get(f"pl_editor_ver{sfx}", 0)
        ev = st.session_state.get(f"pl_tree_view{sfx}_{ver}")
        row_map = st.session_state.get(f"pl_row_map{sfx}", [])
        try: cells = ev["selection"]["cells"]
        except Exception: cells = []
        for cell in cells or []:
            try: r_pos, col = int(cell[0]), str(cell[1])
            except Exception: continue
            if col in _CLICK_COLS and 0 <= r_pos < len(row_map) and row_map[r_pos][1]:
                _open = st.session_state[f"pl_open_nodes{sfx}"]
                if row_map[r_pos][0] in _open: _open.discard(row_map[r_pos][0])
                else: _open.add(row_map[r_pos][0])
        st.session_state[f"pl_editor_ver{sfx}"] = ver + 1     # fresh table (no selection left behind) after every click

    if not visible_idx:
        st.warning("No rows to show."); return
    sub = master_pl.loc[visible_idx]
    depth_col, fmt_col = sub["Depth"].tolist(), sub["_fmt"].tolist()
    is_open = [node_info[i]["node"] in open_nodes for i in visible_idx]
    has_ch = [node_info[i]["has_children"] for i in visible_idx]
    rows = []
    for k, (_, r) in enumerate(sub.iterrows()):
        mark = ("[-] " if is_open[k] else "[+] ") if has_ch[k] else ""
        d = {"Si No": r["Si No"]}
        for lv in ("1", "2", "3", "4"):
            txt = r[f"Level {lv}"]
            d[f"Level {lv}"] = (mark + str(txt)) if (depth_col[k] == f"L{lv}") else txt
        for c in display_columns: d[c] = _fmt_val(r[c], fmt_col[k])
        rows.append(d)
    view = pd.DataFrame(rows)
    head_col = {"L1": "Level 1", "L2": "Level 2", "L3": "Level 3", "L4": "Level 4"}

    def _row_css(r):
        k = r.name
        num_col = LVL_COLOR.get(depth_col[k], T_GOLD)
        out = []
        for c in r.index:
            if c in display_columns:
                col = T_NEG if (isinstance(r[c], str) and r[c].startswith("-")) else num_col
            elif c == head_col.get(depth_col[k]) and is_open[k]:
                col = T_OPEN
            else:
                col = T_ROWHDR
            out.append(f"background-color: {T_NAVY}; font-weight: 400; color: {col};")
        return out
    sty = view.style.apply(_row_css, axis=1)
    _px = px or {"Si No": 52, "Level 1": 235, "Level 2": 185, "Level 3": 120, "Level 4": 100}
    def _cfg(modern):
        cfg = {}
        for c, w in _px.items():
            kw = dict(width=w, pinned=True) if modern else dict(width=("small" if w < 100 else "medium"))
            cfg[c] = st.column_config.TextColumn(c, help="Click a heading with [+] to expand it, [-] to collapse it", **kw)
        return cfg
    ver = st.session_state.get(f"pl_editor_ver{sfx}", 0)
    h = min(35 * (len(view) + 1) + 5, 1100)
    for data, modern in ((sty, True), (sty, False), (view, True), (view, False)):
        try:
            st.dataframe(data, column_config=_cfg(modern), width="stretch", hide_index=True, height=h,
                         key=f"pl_tree_view{sfx}_{ver}", on_select=_click_cb, selection_mode="single-cell")
            return
        except Exception:
            continue
    st.dataframe(view, hide_index=True, height=h)
    st.warning("Expand / collapse needs Streamlit 1.45 or later - check requirements.txt.")

def render_pl_tree(master_pl, sfx="", px=None):
    _tree_fragment(master_pl.reset_index(drop=True), sfx, px)

# ---- page content as sections (used by the Excel / PDF downloads) ----
def _sec(title, df, fmt="lac", bold=None, tree=False, sfx=None, caption=None):
    return {"title": title, "df": df, "fmt": fmt, "bold": bold, "tree": tree, "sfx": sfx, "caption": caption}

def page_sections(page, sel="All"):
    prods = products if sel == "All" else [sel]
    S = []
    if page == "PL":
        S += [_sec("1. PL : Value (Rs in Lacs)", PL_VAL[sel], "row", tree=True, sfx=""),
              _sec("2. PL : % against Sales", PL_PCT[sel], "row", tree=True, sfx="_pct"),
              _sec("3. PL : Cost per Kg against Sale Qt (Rs/Kg)", PL_PU[sel], "row", tree=True, sfx="_pu")]
    elif page == "Revenue":
        S += [_sec("1. Revenue (Rs in Lacs)", pick_rev(sel)), _sec("2. Sale (Qt)", pick_matrix(df_qty_final, qty_matrix, sel), "qt"),
              _sec("3. Due Forecast : Sales (Rs in Lacs)", debtor_due_df(prods)), _sec("4. Debtors & Cash Inflow Forecast (Rs in Lacs)", debtor_flow_df(prods))]
    elif page == "FG":
        S += [_sec("1. FG Flow (Qt)", pick_fg_flow(sel), "qt"), _sec("2. Production (Qt)", pick_matrix(df_summary_prod, fg_prod_matrix, sel), "qt"),
              _sec("3. FG Closing Stock (Qt)", pick_matrix(df_summary_cl, fg_cl_matrix, sel), "qt"), _sec("4. FG Opening Stock (Qt)", pick_matrix(df_summary_op, fg_op_matrix, sel), "qt"),
              _sec("5. FG Closing Stock (Rs in Lacs)", pick_matrix(df_fg_cl_val_final, fg_cl_val, sel)), _sec("6. FG Opening Stock (Rs in Lacs)", pick_matrix(df_fg_op_val_final, fg_op_val, sel))]
    elif page == "RM Qt":
        S += [_sec("1. RM Flow (Qt)", pick_rm_flow(sel, master_rm_flow_df, rm_op_p, rm_purch_p, rm_cons_p, rm_cl_p, "RM Flow(Qt) Metrics"), "qt"),
              _sec("2. RM Consumption (Qt)", pick_rm(sel, df_rm_consumption_final, rm_cons_p), "qt"), _sec("3. RM Purchase (Qt)", pick_rm(sel, df_rm_purchase_final, rm_purch_p), "qt"),
              _sec("4. RM Loss (Qt)", pick_rm(sel, df_rm_loss_final, rm_loss_p), "qt"), _sec("5. Scrap (Qt)", pick_scrap(sel), "qt")]
    elif page == "RM Val":
        S += [_sec("1. RM Flow (Rs in Lacs)", pick_rm_flow(sel, master_rm_val_flow_df, rm_op_val_p, rm_purch_val_p, rm_cons_val_p, rm_cl_val_p, "RM Flow(Rs) Metrics")),
              _sec("2. RM Purchase (Rs in Lacs)", pick_rm(sel, df_rm_purchase_val_final, rm_purch_val_p)), _sec("3. RM Consumption (Rs in Lacs)", pick_rm(sel, df_rm_consumption_val_final, rm_cons_val_p)),
              _sec("4. RM Loss (Rs in Lacs)", pick_rm(sel, df_rm_loss_val_final, rm_loss_val_p)), _sec("5. RM Opening Stock (Rs in Lacs)", pick_rm(sel, df_rm_op_val_final, rm_op_val_p)),
              _sec("6. RM Closing Stock (Rs in Lacs)", pick_rm(sel, df_rm_cl_val_final, rm_cl_val_p)),
              _sec("7. Due to Suppliers (Rs in Lacs) - all products", creditor_due_df()), _sec("8. Creditors & Cash Outflow (Rs in Lacs) - all products", creditor_flow_df())]
    elif page in ("Direct Expenses", "Indirect Expenses"):
        dx = page == "Direct Expenses"
        heads, short, cost, tot = (direct_heads, dx_short, dx_cost, dx_total_cost) if dx else (indirect_heads, ix_short, ix_cost, ix_total_cost)
        for h, s, c in [(h, short[h], cost[h]) for h in heads] + [(f"Total {page}", "Total Exp", tot)]:
            a, b, d = (dx_tables if dx else ix_tables)(c, sel)
            S += [_sec(f"{h} : Forecast (Rs in Lacs)", a), _sec(f"{s} / p.u. (Rs/Kg)", b, "num"), _sec(f"{s} Turnover %", d, "pct")]
    elif page == "Costing":
        for p in prods: S.append(_sec(f"COGS Per Unit : {p} (Rs/Kg)", build_costing_df(p), "num"))
    elif page == "WC":
        a, b = wc_req_df(), wc_dp_df()
        S += [_sec("1. Working Capital Requirement (Rs in Lacs)", a[0], bold=a[1]), _sec("2. Drawing Power, Borrowing & Interest on WC (Rs in Lacs)", b[0], bold=b[1])]
    elif page == "FAR":
        S += [_sec(h, d) for h, d in far_tables()]
    elif page == "TL":
        S += [_sec(h, d) for h, d in tl_tables()]
    elif page == "GST":
        a, b = gst_df(), gst_cf_df()
        S += [_sec("1. GST Input v Output, Current Asset, Cash Outflow (Rs in Lacs)", a[0], bold=a[1]), _sec("2. GST : Hit to Cash Flow (Rs in Lacs)", b[0], bold=b[1])]
    elif page == "CF":
        S += [_sec("Cash Flow : Forecast (Rs in Lacs)", df_cf, "row", tree=True, sfx="_cf")]
    return S

PAGES = [("PL", "PL Forecast", "slicer_pl"), ("Revenue", "Sales Forecasting", "slicer_rev"), ("FG", "Production Forecasting", "slicer_fg"),
         ("RM Qt", "Material Forecasting", "slicer_rmqt"), ("RM Val", "Material Forecasting", "slicer_rmval"),
         ("Direct Expenses", "Direct Expenses Forecast", "slicer_dx"), ("Indirect Expenses", "Indirect Expenses Forecast", "slicer_ix"),
         ("Costing", "Costing : COGS Per Unit", "slicer_cost"), ("WC", "Working Capital Forecast", None), ("FAR", "Fixed Asset Register (FAR)", None),
         ("TL", "Term Loan (TL)", None), ("GST", "GST Forecast", None), ("CF", "Cash Flow : Forecast", None)]
PAGE_TITLE = {p: t for p, t, _ in PAGES}

def _label_cols(df):
    return [c for c in df.columns if c not in display_columns and not str(c).startswith("_") and c not in ("BlockID", "Depth")]
def _bold_rows(sec):
    df = sec["df"].reset_index(drop=True)
    if sec["bold"] is not None: return list(sec["bold"])
    if sec["tree"]: return [d == "L1" for d in df["Depth"]]
    out = []
    for _, r in df.iterrows():
        b = any(str(r[c]).strip() == "Total" for c in _label_cols(df))
        if "Sl No" in df.columns and str(r["Sl No"]).strip() != "": b = True
        out.append(b)
    return out

# ---- Excel (openpyxl) : navy / gold headings, figures as numbers; PL / CF fully expanded with Excel's own +/- grouping ----
_XL_FMT = {"lac": '#,##0.00 "L";[Red]-#,##0.00 "L"', "qt": '#,##0;[Red]-#,##0', "num": '#,##0.00;[Red]-#,##0.00',
           "rate": '#,##0.00;[Red]-#,##0.00', "pct": '0.00"%";[Red]-0.00"%"'}
def _xl_sheet(wb, name, title, sections):
    from openpyxl.styles import Font, PatternFill, Alignment
    ws = wb.create_sheet(name[:31])
    ws.sheet_properties.outlinePr.summaryBelow = False          # the +/- button sits on the heading row, above its detail rows
    navy_f, gold_f = PatternFill("solid", fgColor="00294A"), PatternFill("solid", fgColor="F6EBC4")
    ws.cell(row=1, column=1, value=title).font = Font(bold=True, size=14, color="00294A")
    ws.cell(row=2, column=1, value=f"Bodha Vitta  |  Generated {_dt.date.today():%d %b %Y}  |  Rs in Lacs unless stated").font = Font(italic=True, size=9, color="7A6A2E")
    r0, maxlab = 4, 1
    for sec in sections:
        df = sec["df"].reset_index(drop=True)
        labs = _TREE_LBL if sec["tree"] else _label_cols(df)
        maxlab = max(maxlab, len(labs))
        bold = _bold_rows(sec)
        c = ws.cell(row=r0, column=1, value=sec["title"]); c.font = Font(bold=True, size=11, color="00294A"); c.fill = gold_f
        for j in range(2, len(labs) + len(display_columns) + 1): ws.cell(row=r0, column=j).fill = gold_f
        r0 += 1
        for j, h in enumerate(labs + display_columns, start=1):
            c = ws.cell(row=r0, column=j, value=h); c.font = Font(bold=True, color="FFD24C"); c.fill = navy_f
            c.alignment = Alignment(horizontal="left" if j <= len(labs) else "right")
        r0 += 1
        for i, (_, r) in enumerate(df.iterrows()):
            fmt = r["_fmt"] if (sec["fmt"] == "row" and "_fmt" in df.columns) else sec["fmt"]
            for j, h in enumerate(labs, start=1):
                v = r.get(h, "")
                v = "" if _blank(v) else (str(v).replace(" ", " ") if isinstance(v, str) else v)
                c = ws.cell(row=r0, column=j, value=v)
                if bold[i]: c.font = Font(bold=True)
            for j, h in enumerate(display_columns, start=len(labs) + 1):
                v = r.get(h)
                if _blank(v): continue
                c = ws.cell(row=r0, column=j, value=float(safe_float(v))); c.number_format = _XL_FMT.get(fmt, _XL_FMT["num"])
                if bold[i]: c.font = Font(bold=True)
            if sec["tree"]:
                lvl = {"L1": 0, "L2": 1, "L3": 2, "L4": 3}.get(r["Depth"], 0)
                if lvl: ws.row_dimensions[r0].outline_level = lvl
            r0 += 1
        r0 += 2
    from openpyxl.utils import get_column_letter
    for j in range(1, maxlab + len(display_columns) + 1):
        ws.column_dimensions[get_column_letter(j)].width = 30 if j <= maxlab else 13
    ws.sheet_view.showGridLines = False
    return ws

def build_excel(pages, sel="All", extra_pl_products=False):
    from openpyxl import Workbook
    wb = Workbook(); wb.remove(wb.active)
    for pg in pages:
        _xl_sheet(wb, pg, f"{PAGE_TITLE[pg]}{'' if sel == 'All' else '  -  Product : ' + sel}", page_sections(pg, sel))
    if extra_pl_products:
        for p in products:
            _xl_sheet(wb, f"PL {p}", f"PL Forecast - Product : {p}", page_sections("PL", p))
    bio = BytesIO(); wb.save(bio)
    return bio.getvalue()

# ---- PDF (reportlab) : A3 landscape, Bodha Vitta logo + title on every page, PL / CF as expanded on screen ----
def build_pdf(pages, sel="All"):
    from reportlab.lib.pagesizes import A3, landscape
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.utils import ImageReader
    W, H = landscape(A3)
    NAVY, GOLD, NEG = colors.HexColor("#00294A"), colors.HexColor("#D4AF37"), colors.HexColor("#C62828")
    logo = ImageReader(BytesIO(base64.b64decode(LOGO_PDF_B64)))
    head = {"txt": ""}
    def _decor(cv, doc):
        cv.saveState()
        cv.drawImage(logo, 22, H - 62, width=42, height=47, mask="auto")
        cv.setFillColor(NAVY); cv.setFont("Helvetica-Bold", 15); cv.drawString(74, H - 36, "Bodha Vitta")
        cv.setFont("Helvetica", 9); cv.setFillColor(colors.HexColor("#7A6A2E")); cv.drawString(74, H - 50, head["txt"])
        cv.drawRightString(W - 22, H - 36, f"Generated {_dt.date.today():%d %b %Y}")
        cv.setStrokeColor(GOLD); cv.setLineWidth(1.5); cv.line(22, H - 68, W - 22, H - 68)
        cv.setFont("Helvetica", 7); cv.setFillColor(colors.grey); cv.drawRightString(W - 22, 14, f"Page {doc.page}")
        cv.restoreState()
    h1 = ParagraphStyle("h1", fontName="Helvetica-Bold", fontSize=13, textColor=NAVY, spaceAfter=4)
    h2 = ParagraphStyle("h2", fontName="Helvetica-Bold", fontSize=9.5, textColor=NAVY, spaceBefore=8, spaceAfter=3)
    story, avail = [], W - 44
    for pi, pg in enumerate(pages):
        if pi: story.append(PageBreak())
        story.append(Paragraph(f"{PAGE_TITLE[pg]}{'' if sel == 'All' else '  -  Product : ' + sel}", h1))
        for sec in page_sections(pg, sel):
            df = sec["df"].reset_index(drop=True)
            bold = _bold_rows(sec)
            if sec["tree"]:                                     # as expanded on screen ; one 'Particulars' column, indented by level
                vis, _info, _open = tree_visible(df, sec["sfx"])
                rows_idx = vis
                labels = []
                for i in vis:
                    d = df.at[i, "Depth"]; lv = int(str(d)[1])
                    labels.append([str(df.at[i, "Si No"]), "    " * (lv - 1) + str(df.at[i, f"Level {lv}"])])
                lab_hdr, lab_w = ["Si No", "Particulars"], [26, 190]
            else:
                rows_idx = list(range(len(df)))
                lcols = _label_cols(df)
                labels = [["" if _blank(df.at[i, c]) else str(df.at[i, c]).replace(" ", " ") for c in lcols] for i in rows_idx]
                lab_hdr = lcols
                lens = [max([len(str(c))] + [len(l[k]) for l in labels]) for k, c in enumerate(lcols)]
                budget = 240.0
                lab_w = [max(24.0, budget * n / max(sum(lens), 1)) for n in lens]
            num_w = (avail - sum(lab_w)) / len(display_columns)
            data = [lab_hdr + display_columns]
            negs = []
            for k, i in enumerate(rows_idx):
                fmt = df.at[i, "_fmt"] if (sec["fmt"] == "row" and "_fmt" in df.columns) else sec["fmt"]
                vals = []
                for j, c in enumerate(display_columns):
                    v = df.at[i, c]
                    if _blank(v): vals.append("")
                    else:
                        fv = safe_float(v); vals.append(_fmt_val(fv, fmt))
                        if fv < 0: negs.append((len(lab_hdr) + j, k + 1))
                data.append(labels[k] + vals)
            t = Table(data, colWidths=lab_w + [num_w] * len(display_columns), repeatRows=1)
            ts = [("FONT", (0, 0), (-1, -1), "Helvetica", 6.3), ("FONT", (0, 0), (-1, 0), "Helvetica-Bold", 6.5),
                  ("BACKGROUND", (0, 0), (-1, 0), NAVY), ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#FFD24C")),
                  ("ALIGN", (len(lab_hdr), 0), (-1, -1), "RIGHT"), ("LINEBELOW", (0, 0), (-1, -1), 0.25, colors.HexColor("#E3DCC2")),
                  ("TOPPADDING", (0, 0), (-1, -1), 1.6), ("BOTTOMPADDING", (0, 0), (-1, -1), 1.6), ("VALIGN", (0, 0), (-1, -1), "MIDDLE")]
            for k, i in enumerate(rows_idx):
                if bold[i]: ts += [("FONT", (0, k + 1), (-1, k + 1), "Helvetica-Bold", 6.3), ("BACKGROUND", (0, k + 1), (-1, k + 1), colors.HexColor("#FBF6E6"))]
            for (cx, ry) in negs: ts.append(("TEXTCOLOR", (cx, ry), (cx, ry), NEG))
            t.setStyle(TableStyle(ts))
            story.append(KeepTogether([Paragraph(sec["title"], h2)]))
            story.append(t)
            story.append(Spacer(1, 6))
    head["txt"] = ("Full Model" if len(pages) > 1 else PAGE_TITLE[pages[0]]) + f"  |  Product : {sel}  |  Rs in Lacs unless stated"
    bio = BytesIO()
    doc = SimpleDocTemplate(bio, pagesize=landscape(A3), leftMargin=22, rightMargin=22, topMargin=78, bottomMargin=26,
                            title=f"Bodha Vitta - {'Full Model' if len(pages) > 1 else PAGE_TITLE[pages[0]]}", author="Bodha Vitta")
    doc.build(story, onFirstPage=_decor, onLaterPages=_decor)
    return bio.getvalue()

def _dl_body(page, sel):
    """Download dialog : choose Excel or PDF, then save. The file is built only now, so normal use of the app stays fast."""
    full = page is None
    pages = [p for p, _, _ in PAGES] if full else [page]
    st.markdown(f"**{'Full Model (all pages)' if full else PAGE_TITLE[page] + ' (' + page + ' page)'}**  ·  Product : {sel}")
    st.caption("Excel : every figure as a number; PL and Cash Flow fully expanded with Excel's own +/- grouping."
               + ("  Full-model Excel also has the PL of every product." if full else "")
               + "  PDF : A3 landscape with the Bodha Vitta logo; PL and Cash Flow as expanded on screen.")
    c1, c2 = st.columns(2)
    if c1.button("📊  Excel", key="dlg_xl"): st.session_state["_dl_fmt"] = "xlsx"
    if c2.button("📄  PDF", key="dlg_pdf"): st.session_state["_dl_fmt"] = "pdf"
    fmt = st.session_state.get("_dl_fmt")
    if fmt:
        stem = ("Full_Model" if full else page.replace(" ", "_")) + ("" if sel == "All" else f"_{sel}") + f"_{_dt.date.today():%Y%m%d}"
        with st.spinner("Preparing the file ..."):
            try:
                data = build_excel(pages, sel, extra_pl_products=full) if fmt == "xlsx" else build_pdf(pages, sel)
            except ImportError as e:
                st.error(f"Library missing ({e.name}) - add 'openpyxl' and 'reportlab' to requirements.txt and reboot the app."); return
        st.download_button(f"⬇  Save {stem}.{fmt}", data=data, file_name=f"{stem}.{fmt}", key="dlg_save",
                           mime=("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" if fmt == "xlsx" else "application/pdf"))
dl_dialog = _dialog("Download")(_dl_body) if _dialog else None

def open_download(page, sel):
    st.session_state["_dl_fmt"] = None
    if dl_dialog: dl_dialog(page, sel)
    else:
        with st.expander("Download", expanded=True): _dl_body(page, sel)

def page_header(page, slicer_key=None):
    """Page title, Product slicer (if the page has one) and the Download button at the top right."""
    if slicer_key:
        c_t, c_s, c_d = st.columns([6, 1.4, 1.1], vertical_alignment="center")
    else:
        c_t, c_d = st.columns([7.4, 1.1], vertical_alignment="center")
    with c_t: st.title(PAGE_TITLE[page])
    sel = "All"
    if slicer_key:
        with c_s: sel = st.selectbox("Product", ["All"] + products, key=slicer_key, label_visibility="collapsed", format_func=lambda x: f"Product : {x}")
    with c_d:
        if st.button("⬇ Download", key=f"dl_btn_{page}", help="Download this page as Excel or PDF"):
            open_download(page, sel)
    return sel

